this.setBaseApiUrl(); 

const user = this.$auth.getUserInfo();
this.loggedInUser = user?.fullname || user?.name || user?.username || user?.email || user?.sub || "User";

this.authReadyPromise = this.setSaasAuth(); 
await this.authReadyPromise;

try {
    const result = await this.payrollAuth.workflow_access_control_workflow_users_SelectUserMe({}, {
        headers: {
            "X-Authorization": this.$cookies.get("id_token")
        }
    });

    const user = result?.data?.users_me;
    if (!user || !Array.isArray(user.role_names) || !Array.isArray(user.scopes)) {
        throw new Error(
            "API response is missing the expected user, roles, or scopes data."
        );
    }

    this.saasAuth.rolesByName = user.role_names;
    this.saasAuth.userScopes = user.scopes;
    this.saasAuth.userId = user.Id;
    this.saasAuth.workerId = user.WorkerId;
    this.isCurrentUserAdmin = this.saasAuth.rolesByName.includes("Payroll Admin");

} catch (error) {
    console.error("API Error in authService:", error);
    if (error.response) {
        console.error("Server responded with:", error.response.data);
    }

    throw error;
}

const ENV_PROPERTY_NAME = "payroll_api_base_url";

// Helper function to safely construct a full URL from a base and a path
const getFullApiUrl = (base, path) => {
  if (!base || !path) {
    return null;
  }
  const cleanBase = base.endsWith('/') ? base.slice(0, -1) : base;
  const cleanPath = path.startsWith('/') ? path : `/${path}`;
  return cleanBase + cleanPath;
};

// Get the single base URL from the environment
const apiBaseUrlFromEnv = this.$env.getProperty(ENV_PROPERTY_NAME);

// Central validation for the base URL
if (!apiBaseUrlFromEnv || apiBaseUrlFromEnv.trim() === "") {
  console.warn(`The '${ENV_PROPERTY_NAME}' environment variable is not set. API URLs cannot be configured.`);
} else {
  // Array of API endpoint configurations
  const apiEndpoints = [
    {
      path: "/api/access_control/1.0",
      service: this.payrollAuth, 
      serviceName: "payrollAuth"
    }
  ];

  // Iterate over each configuration to set the URL and configure the service
  apiEndpoints.forEach(endpoint => {
    const fullApiUrl = getFullApiUrl(apiBaseUrlFromEnv, endpoint.path);
    if (endpoint.service && typeof endpoint.service.setServerUrl === 'function') {
      endpoint.service.setServerUrl(fullApiUrl);
    } else {
      console.warn(`The '${endpoint.serviceName}' service or its 'setServerUrl' method is not available.`);
    }
  });
}

const option = {
        entity: "user",
        query: `Id=${Id}`
    };

const result = await this.payrollApiService.get(option);
const workerId = result?.entities?.[0]?.WorkerId ?? null;

return workerId;

await this.authReadyPromise;
if (!this.isCurrentUserAdmin) {
    this.$state.go("user", {userId: this.saasAuth.userId});
    return false;
} else return true;
